<?php
require_once __DIR__.'/../includes/database.php'; require_once __DIR__.'/../includes/stock.php';
function check_stock(bool $condition,string $message): void { if(!$condition)throw new RuntimeException($message); }
function stock_denied(callable $fn,int $status): void {try{$fn();}catch(CatalogException $e){check_stock($e->status===$status,$e->getMessage());return;}throw new RuntimeException('No se rechazó la operación.');}
$url=getenv('REPOTOOLS_TEST_DATABASE_URL');
if($url){$c=postgres_connection($url);$db=new PDO($c['dsn'],$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::PGSQL_ATTR_DISABLE_PREPARES=>true]);}
else $db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
if(getenv('REPOTOOLS_SCHEMA_ONLY_TEST')==='1') {for($v=1;$v<=5;$v++)stock_query($db,'INSERT INTO app_schema_migrations(version) VALUES(?) ON CONFLICT(version) DO NOTHING',[$v]);}
initialize_database($db); initialize_database($db);
$suffix=bin2hex(random_bytes(6)); $users=[];foreach(['Juan','Pedro','Invitado'] as $name)$users[]=(int)stock_query($db,'INSERT INTO users(name,email,password_hash) VALUES(?,?,?) RETURNING id',[$name,$suffix.$name.'@example.invalid','test'])->fetchColumn();[$juan,$pedro,$guest]=$users;
$db->beginTransaction();stock_expire($db);$label=stock_generate($db,$juan);check_stock(strlen($label['code'])===8,'Ocho dígitos.');check_stock((int)$label['reserved_until']>=time()+259190,'Reserva tres días.');check_stock(stock_detail($db,$label['code'],null)['available'],'Generar no activa.');check_stock(!stock_detail($db,$label['code'],$pedro)['can_claim'],'Otro usuario no reclama una reserva.');stock_denied(fn()=>stock_claim($db,$label['code'],$pedro),409);
stock_query($db,'UPDATE pallet_labels SET reserved_until=? WHERE code=?',[time()-1,$label['code']]);stock_expire($db);check_stock(stock_detail($db,$label['code'],$juan)['can_claim'],'Después de vencer puede volver a utilizarse.');
$first=stock_claim($db,$label['code'],$juan);$second=stock_claim($db,$label['code'],$pedro);check_stock($first['code']!==$second['code']&&$second['relocated'],'Activación simultánea conserva al primero y reasigna al segundo.');
stock_denied(fn()=>stock_editable($db,$first['id'],$pedro),403);
$input=['pallet_id'=>$first['id'],'ean'=>'96385074','name'=>'Marca Agua 1 L','amount'=>8,'kind'=>'boxes','pack_size'=>5,'expires'=>'2026-12-24'];stock_save_product($db,$juan,$input);stock_save_product($db,$juan,[...$input,'amount'=>2,'kind'=>'units']);
$p=stock_detail($db,$first['code'],null);check_stock($p['products'][0]['units']==42,'Mismo EAN y fecha suman unidades.');check_stock($p['owner_name']==='Juan'&&!isset($p['owner_id']),'Ficha pública sin identificadores privados.');
stock_save_product($db,$juan,[...$input,'amount'=>3,'kind'=>'units','expires'=>'']);$p=stock_detail($db,$first['code'],$juan);check_stock(count($p['products'])===2,'Distinto vencimiento crea otro lote.');$product=array_values(array_filter($p['products'],fn($b)=>$b['expires']===''))[0];
stock_save_product($db,$juan,[...$input,'product_id'=>$product['id'],'revision'=>$product['revision'],'amount'=>3,'kind'=>'units']);$p=stock_detail($db,$first['code'],$juan);check_stock(count($p['products'])===1&&$p['products'][0]['units']==45,'Editar vencimiento combina los lotes.');
stock_denied(fn()=>stock_save_product($db,$juan,[...$input,'product_id'=>$p['products'][0]['id'],'revision'=>0]),409);
stock_denied(fn()=>stock_product_input([...$input,'expires'=>'2026-02-30']),422);stock_denied(fn()=>stock_product_input([...$input,'amount'=>-1]),422);stock_denied(fn()=>stock_product_input([...$input,'ean'=>'55007732']),422);
stock_query($db,"INSERT INTO pallet_access(pallet_id,user_id,status) VALUES(?,?,'pending')",[$first['id'],$guest]);stock_denied(fn()=>stock_editable($db,$first['id'],$guest),403);stock_query($db,"UPDATE pallet_access SET status='accepted' WHERE pallet_id=? AND user_id=?",[$first['id'],$guest]);check_stock(stock_editable($db,$first['id'],$guest)['id']===$first['id'],'Aceptado puede editar.');stock_denied(fn()=>stock_editable($db,$first['id'],$guest,true),403);
stock_query($db,'UPDATE pallets SET prepared_until=? WHERE id=?',[time()-1,$first['id']]);stock_expire($db);check_stock(!stock_detail($db,$first['code'],$juan)['available'],'Con productos no vence.');stock_query($db,'DELETE FROM pallet_products WHERE pallet_id=?',[$first['id']]);stock_expire($db);check_stock(!stock_detail($db,$first['code'],$juan)['available'],'Vaciar no libera un palet activado.');
stock_query($db,'UPDATE pallets SET prepared_until=? WHERE id=?',[time()-1,$second['id']]);stock_expire($db);check_stock(stock_detail($db,$second['code'],$pedro)['available'],'Sin primer producto vence en tres días.');
stock_query($db,'UPDATE pallets SET released=1 WHERE id=?',[$first['id']]);stock_expire($db);$reused=stock_claim($db,$first['code'],$pedro);check_stock($reused['id']!==$first['id'],'Reutiliza etiqueta sin mezclar permisos o historial.');
$date=(new DateTimeImmutable('today',new DateTimeZone('America/Buenos_Aires')))->modify('+2 days')->format('Y-m-d');stock_save_product($db,$pedro,[...$input,'pallet_id'=>$reused['id'],'expires'=>$date]);stock_query($db,'INSERT INTO stock_preferences(user_id,expiry_days) VALUES(?,0)',[$pedro]);stock_notify($db,$pedro);check_stock(!stock_query($db,'SELECT id FROM notifications WHERE user_id=?',[$pedro])->fetchColumn(),'Cero días no se convierte en siete.');stock_query($db,'UPDATE stock_preferences SET expiry_days=7 WHERE user_id=?',[$pedro]);stock_notify($db,$pedro);stock_notify($db,$pedro);check_stock((int)stock_query($db,'SELECT COUNT(*) FROM notifications WHERE user_id=?',[$pedro])->fetchColumn()===1,'Aviso de vencimiento sin duplicados.');
$db->commit();echo "OK: reservas, carreras, acceso público, propietarios, lotes, cantidades, conflictos, reutilización y vencimientos.\n";
